import{_ as s,o as a,c as t,a6 as i}from"./chunks/framework.CCKCzdWs.js";const u=JSON.parse('{"title":"Metrics and rollup export","description":"Serve the metric catalog as OpenMetrics for Prometheus and Grafana, and export the daily rollups as JSON or CSV for BI tools.","frontmatter":{"title":"Metrics and rollup export","description":"Serve the metric catalog as OpenMetrics for Prometheus and Grafana, and export the daily rollups as JSON or CSV for BI tools.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/operate/metrics.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/operate/metrics.html"}],["meta",{"property":"og:title","content":"Metrics and rollup export | Piwi Dashboard"}],["meta",{"property":"og:description","content":"Serve the metric catalog as OpenMetrics for Prometheus and Grafana, and export the daily rollups as JSON or CSV for BI tools."}]]},"headers":[],"relativePath":"operate/metrics.md","filePath":"operate/metrics.md","lastUpdated":1793450333000}'),n={name:"operate/metrics.md"};function r(o,e,p,l,c,d){return a(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="metrics-and-rollup-export" tabindex="-1">Metrics and rollup export <a class="header-anchor" href="#metrics-and-rollup-export" aria-label="Permalink to &quot;Metrics and rollup export&quot;">​</a></h1><p>Piwi keeps one row of numbers per project and day (the <a href="/features/analytics.html#where-the-numbers-come-from">daily rollups</a>), and those rows survive <a href="./storage.html#data-retention">data retention</a>. Two endpoints hand them to tools you already run. Both are pulls: <strong>your Grafana pulls from your Piwi</strong>, and Piwi sends nothing anywhere, so neither changes the &quot;zero telemetry&quot; promise.</p><h2 id="openmetrics-for-prometheus-and-grafana" tabindex="-1">OpenMetrics for Prometheus and Grafana <a class="header-anchor" href="#openmetrics-for-prometheus-and-grafana" aria-label="Permalink to &quot;OpenMetrics for Prometheus and Grafana&quot;">​</a></h2><p><code>GET /api/metrics</code> serves the metric catalog&#39;s current values per project in the OpenMetrics text format. It is <strong>off by default</strong>: set <code>PIWI_METRICS_ENABLED=true</code> to serve it; otherwise it answers 404.</p><ul><li>One gauge family per metric, named after it and its unit: <code>piwi_test_pass_rate_percent</code>, <code>piwi_run_success_rate_percent</code>, <code>piwi_runs</code>, <code>piwi_wasted_ci_minutes_minutes</code>, <code>piwi_open_failure_causes</code>, <code>piwi_median_time_to_fix_days</code>, … Each family&#39;s <code>HELP</code> line carries the metric&#39;s definition.</li><li>One sample per project, labeled <code>project</code> and <code>project_id</code>. A metric with nothing to count in the period (no run) has no sample, rather than a zero.</li><li>The values cover the last 7 days on each project&#39;s default branch; <code>?period=last-30d</code> or <code>?allBranches=true</code> change that, with the scope keys of the analytics page.</li><li>Answers are cached for 60 seconds, so a scrape interval under a minute reads the same numbers.</li></ul><p>An answer, cut to three metrics and two projects:</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># TYPE piwi_test_pass_rate_percent gauge</span></span>
<span class="line"><span># UNIT piwi_test_pass_rate_percent percent</span></span>
<span class="line"><span># HELP piwi_test_pass_rate_percent Test pass rate, last 7 days: Tests passed divided by tests run, summed over the runs of the period.</span></span>
<span class="line"><span>piwi_test_pass_rate_percent{project=&quot;checkout&quot;,project_id=&quot;1&quot;} 97.8</span></span>
<span class="line"><span>piwi_test_pass_rate_percent{project=&quot;search&quot;,project_id=&quot;2&quot;} 99.4</span></span>
<span class="line"><span># TYPE piwi_runs gauge</span></span>
<span class="line"><span># HELP piwi_runs Runs, last 7 days: Finished runs in the period.</span></span>
<span class="line"><span>piwi_runs{project=&quot;checkout&quot;,project_id=&quot;1&quot;} 42</span></span>
<span class="line"><span>piwi_runs{project=&quot;search&quot;,project_id=&quot;2&quot;} 31</span></span>
<span class="line"><span># TYPE piwi_wasted_ci_minutes_minutes gauge</span></span>
<span class="line"><span># UNIT piwi_wasted_ci_minutes_minutes minutes</span></span>
<span class="line"><span># HELP piwi_wasted_ci_minutes_minutes Wasted CI minutes, last 7 days: Minutes spent inside wait steps plus minutes spent executing attempts that ended failed or timed out.</span></span>
<span class="line"><span>piwi_wasted_ci_minutes_minutes{project=&quot;checkout&quot;,project_id=&quot;1&quot;} 18.5</span></span>
<span class="line"><span>piwi_wasted_ci_minutes_minutes{project=&quot;search&quot;,project_id=&quot;2&quot;} 2</span></span>
<span class="line"><span># EOF</span></span></code></pre></div><p>With <a href="./authentication.html">authentication</a> on, the scraper sends an <a href="./api-keys.html">API key</a>, and the samples cover the projects that key&#39;s user can open; a browser session is refused. Create a key for a Member with the Viewer role on the projects you want to chart. A Prometheus scrape job:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">scrape_configs</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">job_name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">piwi</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    metrics_path</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/api/metrics</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    scheme</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">https</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # the key travels in a header: never over plain HTTP</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    scrape_interval</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">5m</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    authorization</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      credentials</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">pd_your_api_key</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    static_configs</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">targets</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;piwi.example.com&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span></code></pre></div><h2 id="rollup-export-for-bi-tools" tabindex="-1">Rollup export for BI tools <a class="header-anchor" href="#rollup-export-for-bi-tools" aria-label="Permalink to &quot;Rollup export for BI tools&quot;">​</a></h2><p>The rollups endpoint (in the example below) streams the daily rollup rows of the projects you can open: one row per project, UTC day, environment, branch and run kind, with the history retention deleted still counted. It needs no flag.</p><ul><li><code>?format=csv</code> downloads a CSV for a spreadsheet, Power BI or Metabase; the default <code>json</code> answers <code>{ &quot;items&quot;: [...] }</code>.</li><li>The scope keys of the analytics page narrow it: <code>period</code> (30 days by default; <code>all</code> for everything kept), <code>projects</code>, <code>projectTags</code>, <code>environments</code>, <code>branches</code>, <code>allBranches</code>, <code>fullRunsOnly</code>.</li><li>For an average, divide <code>durationMs</code> by <code>durationRuns</code> (the runs with a duration) and the two <code>*TestDurationSumMs</code> columns by <code>testDurationRuns</code>. <code>maxTotalTests</code> is the largest suite one run reported.</li><li>A cell that could run as a spreadsheet formula (a branch named <code>=…</code>) is prefixed with <code>&#39;</code>.</li></ul><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer pd_your_api_key&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;https://piwi.example.com/api/rollups?format=csv&amp;period=this-year&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rollups.csv</span></span></code></pre></div><p>The column list and every parameter are in the API reference (<code>/docs</code> on your instance).</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/features/analytics.html">Analytics</a>: the metrics, the scope and the periods</li><li><a href="/features/quality-reports.html">Quality reports</a>: the same numbers as a document for a reader</li><li><a href="/reference/configuration.html#general">Configuration reference</a>: <code>PIWI_METRICS_ENABLED</code></li></ul>`,16)])])}const k=s(n,[["render",r]]);export{u as __pageData,k as default};
